//! 🎟️ One true embedding root retains the exact issued scope until its suspended guest receipt returns.
use semio_framework_actor::{RetainedTurnInput,RetainedTurnReceipt,OriginalJobBudget,OriginalGuestExecutionBudget,OriginalGuestExecutionReceipt};
use semio_framework_job::{StepBudget,StepContext,OriginalTurnFailure};
use semio_framework_actor::retained_turn::context::{OriginalActorContextSlot,OriginalActorContextError};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind};

#[derive(Clone,Copy,Debug,PartialEq,Eq,serde::Serialize,serde::Deserialize,semio_framework_value_derive::FromValue,semio_framework_value_derive::ToValue)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
#[value(rename_all="camelCase")]
pub struct GuestRelayRootPolicy{pub operation:u64,pub generation:u64,pub turn_fuel:u64,pub operation_fuel:u64,pub turn_execution_fuel:u64,pub operation_execution_fuel:u64,pub maximum_turn_microseconds:u64,pub max_effects:u32,pub max_patch_bytes:u32,pub max_frames:u32}
impl GuestRelayRootPolicy{
 pub fn validate(self)->Result<(),ValueError>{if self.operation==0||self.generation==0||self.turn_fuel==0||self.operation_fuel==0||self.turn_execution_fuel==0||self.operation_execution_fuel==0||self.maximum_turn_microseconds==0{return Err(refusal("original Host root policy requires explicit positive identity, fuel and callback duration"))}Ok(())}
}
#[derive(Clone,Copy,PartialEq,Eq)]
enum ScopeKey{Receiver{slot:usize,generation:u64},Actor{input:RetainedTurnInput}}
struct Scope{key:ScopeKey,original:RetainedTurnInput,remaining:StepBudget,spent:RetainedCloneProgress,work:u64,pending:Option<OriginalJobBudget>,cancelled:bool,execution_remaining:u64,execution_spent:u64,execution_pending:Option<OriginalGuestExecutionBudget>}
/// 🏛️ Root admission, caller inputs and receipt storage are retained separately from guest job ids.
pub struct GuestRelayOriginalRoot{policy:GuestRelayRootPolicy,clock:fn()->Option<u64>,context:OriginalActorContextSlot,scope:Option<Scope>,recipient:RetainedCloneProgress,ready:bool,fuel_remaining:u64,execution_fuel_remaining:u64}
impl GuestRelayOriginalRoot{
 pub fn new(policy:GuestRelayRootPolicy,clock:fn()->Option<u64>)->Result<Self,ValueError>{policy.validate()?;clock().ok_or_else(||refusal("original Host root requires its supplied lifetime clock"))?;Ok(Self{policy,clock,context:OriginalActorContextSlot::empty(),scope:None,recipient:Default::default(),ready:false,fuel_remaining:policy.operation_fuel,execution_fuel_remaining:policy.operation_execution_fuel})}
 pub fn policy(&self)->GuestRelayRootPolicy{self.policy}
 pub fn ready(&self)->bool{self.ready}
 pub fn fuel_remaining(&self)->u64{self.fuel_remaining}
 pub fn execution_fuel_remaining(&self)->u64{self.execution_fuel_remaining}
 pub fn clock_source(&self)->fn()->Option<u64>{self.clock}
 fn validate_input(&self,input:RetainedTurnInput)->Result<(),ValueError>{input.validate()?;if(input.operation,input.generation)!=(self.policy.operation,self.policy.generation){return Err(refusal("original Host root input belongs to another declared operation"))}Ok(())}
 pub fn issued_budget(&self,input:RetainedTurnInput)->Result<StepBudget,ValueError>{self.validate_input(input)?;if self.scope.is_some(){return Err(refusal("original Host root cannot issue a new scope before its original receipt returns"))}let now=(self.clock)().ok_or_else(||refusal("original Host root lost its original clock"))?;let deadline=now.checked_add(self.policy.maximum_turn_microseconds).ok_or_else(||refusal("original Host root deadline overflow"))?;Ok(StepBudget::new(self.policy.turn_fuel.min(self.fuel_remaining),deadline,input.grant))}
 pub fn admit_step(&mut self,input:RetainedTurnInput)->Result<(bool,RetainedCloneProgress,u64),ValueError>{self.validate_input(input)?;if self.scope.is_some(){return Err(refusal("original Host root admission overlaps its suspended turn"))}if self.ready{return Ok((true,Default::default(),0))}let call=self.context.admit_step(input);let work=u64::from(call.receipt_spent!=Default::default());self.fuel_remaining=self.fuel_remaining.checked_sub(work).ok_or_else(||refusal("original Host admission exceeds finite fuel"))?;let admission=call.result?;self.ready=admission.ready;Ok((self.ready,call.receipt_spent,work))}
 pub fn begin_turn(&mut self,slot:usize,generation:u64,input:RetainedTurnInput,budget:StepBudget)->Result<(),ValueError>{if generation==0{return Err(refusal("original Host retained receiver has no generation"))}self.begin_scope(ScopeKey::Receiver{slot,generation},input,budget)}
 pub fn begin_actor_scope(&mut self,input:RetainedTurnInput,budget:StepBudget)->Result<(),ValueError>{self.begin_scope(ScopeKey::Actor{input},input,budget)}
 fn begin_scope(&mut self,key:ScopeKey,input:RetainedTurnInput,budget:StepBudget)->Result<(),ValueError>{self.validate_input(input)?;if !self.ready||self.scope.is_some()||budget.retained!=input.grant||budget.fuel>self.policy.turn_fuel||budget.fuel>self.fuel_remaining{return Err(refusal("original Host root scope is absent, overlapping or exceeds its original policy"))}self.context.begin_pending_context(input)?;self.recipient=Default::default();self.scope=Some(Scope{key,original:input,remaining:budget,spent:Default::default(),work:0,pending:None,cancelled:false,execution_remaining:self.policy.turn_execution_fuel.min(self.execution_fuel_remaining),execution_spent:0,execution_pending:None});Ok(())}
 fn matching(&self,slot:usize,generation:u64)->Result<&Scope,ValueError>{self.matching_key(ScopeKey::Receiver{slot,generation})}
 fn matching_key(&self,key:ScopeKey)->Result<&Scope,ValueError>{let scope=self.scope.as_ref().ok_or_else(||refusal("original Host root has no issued scope"))?;if scope.key!=key{return Err(refusal("original Host root scope belongs to another retained owner"))}Ok(scope)}
 pub fn dispatch_actor_step<T>(&mut self,input:RetainedTurnInput,cancelled:bool,produce:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->Result<T,OriginalTurnFailure>{self.borrow_key(ScopeKey::Actor{input},cancelled,produce)}
 pub fn actor_budget(&self,input:RetainedTurnInput)->Result<OriginalJobBudget,ValueError>{let scope=self.matching_key(ScopeKey::Actor{input})?;Ok(OriginalJobBudget{input:RetainedTurnInput{grant:scope.remaining.retained,..scope.original},fuel:scope.remaining.fuel,deadline_us:scope.remaining.deadline_us,cancelled:scope.cancelled})}
 pub fn receive_actor_spent(&mut self,input:RetainedTurnInput,spent:RetainedCloneProgress,cancelled:bool)->Result<(),OriginalTurnFailure>{self.dispatch_actor_step(input,cancelled,|cx|{cx.consume_retained(spent)?;Ok(())})}
 pub fn finish_actor_scope(&mut self,input:RetainedTurnInput)->Result<(RetainedTurnReceipt,u64,u64),ValueError>{self.finish_key(ScopeKey::Actor{input})}
 pub fn pending_budget(&self,slot:usize,generation:u64)->Result<OriginalJobBudget,ValueError>{let scope=self.matching(slot,generation)?;Ok(OriginalJobBudget{input:RetainedTurnInput{grant:scope.remaining.retained,..scope.original},fuel:scope.remaining.fuel,deadline_us:scope.remaining.deadline_us,cancelled:scope.cancelled})}
 fn matches_pending(&self,slot:usize,generation:u64,expected:OriginalJobBudget)->Result<(),ValueError>{let actual=self.pending_budget(slot,generation)?;if actual.input!=expected.input||actual.fuel!=expected.fuel||actual.deadline_us!=expected.deadline_us{return Err(refusal("original Host pending receipt attempted to change its initiating scope"))}Ok(())}
 pub fn hold_pending(&mut self,slot:usize,generation:u64,expected:OriginalJobBudget)->Result<(),ValueError>{self.matches_pending(slot,generation,expected)?;let scope=self.scope.as_mut().unwrap();if scope.pending.is_some(){return Err(refusal("original Host scope already retains a guest receipt"))}scope.pending=Some(expected);Ok(())}
 pub fn dispatch_step<T>(&mut self,slot:usize,generation:u64,cancelled:bool,produce:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->Result<T,OriginalTurnFailure>{if self.matching(slot,generation)?.pending.is_some(){return Err(refusal("original Host semantic callback cannot overlap a guest receipt").into())}self.borrow_scope(slot,generation,cancelled,produce)}
 pub fn dispatch_pending_step<T>(&mut self,slot:usize,generation:u64,expected:OriginalJobBudget,cancelled:bool,produce:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->Result<T,OriginalTurnFailure>{self.matches_pending(slot,generation,expected)?;if self.scope.as_ref().unwrap().pending!=Some(expected){return Err(refusal("original Host receipt callback has no exact retained guest loan").into())}self.borrow_scope(slot,generation,cancelled,produce)}
 fn borrow_scope<T>(&mut self,slot:usize,generation:u64,cancelled:bool,produce:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->Result<T,OriginalTurnFailure>{
  self.borrow_key(ScopeKey::Receiver{slot,generation},cancelled,produce)
 }
 fn borrow_key<T>(&mut self,key:ScopeKey,cancelled:bool,produce:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->Result<T,OriginalTurnFailure>{
  self.matching_key(key)?;let scope=self.scope.as_mut().unwrap();self.recipient=Default::default();let input=RetainedTurnInput{grant:scope.remaining.retained,..scope.original};let before_fuel=scope.remaining.fuel;
  let(result,remaining,fuel,spent)={let mut cx=self.context.borrow_pending_context(input,scope.remaining,&mut self.recipient,self.clock)?;if cancelled{cx.borrowed_original_cancel_token()?.cancel_now();}let result=produce(&mut cx);(result,cx.retained_grant(),cx.fuel_remaining(),cx.retained_progress())};
  scope.cancelled|=cancelled;scope.remaining=StepBudget::new(fuel,scope.remaining.deadline_us,remaining);scope.work=scope.work.checked_add(before_fuel-fuel).ok_or_else(||refusal("original Host cumulative fuel overflow"))?;scope.spent=add(scope.spent,spent)?;if !scope.spent.fits(scope.original.grant){return Err(refusal("original Host physical receipts exceed the initiating scope").into())}result
 }
 pub fn acknowledge_pending(&mut self,slot:usize,generation:u64,expected:OriginalJobBudget)->Result<(),ValueError>{self.matching(slot,generation)?;if self.scope.as_ref().unwrap().pending!=Some(expected){return Err(refusal("original Host pending receipt acknowledgement differs from its held loan"))}self.scope.as_mut().unwrap().pending=None;Ok(())}
 pub fn checkout_execution_budget(&mut self,slot:usize,generation:u64,guest:OriginalJobBudget)->Result<OriginalGuestExecutionBudget,ValueError>{self.matches_pending(slot,generation,guest)?;self.checkout_execution_key(ScopeKey::Receiver{slot,generation},guest)}
 pub fn checkout_actor_execution_budget(&mut self,input:RetainedTurnInput)->Result<OriginalGuestExecutionBudget,ValueError>{let guest=self.actor_budget(input)?;self.checkout_execution_key(ScopeKey::Actor{input},guest)}
 fn checkout_execution_key(&mut self,key:ScopeKey,guest:OriginalJobBudget)->Result<OriginalGuestExecutionBudget,ValueError>{self.matching_key(key)?;let scope=self.scope.as_mut().unwrap();if scope.execution_pending.is_some(){return Err(refusal("original Host execution receipt is already outstanding"))}let budget=OriginalGuestExecutionBudget{input:guest.input,fuel:scope.execution_remaining,deadline_us:guest.deadline_us};budget.validate_for(guest)?;scope.execution_pending=Some(budget);Ok(budget)}
 pub fn receive_execution_receipt(&mut self,slot:usize,generation:u64,receipt:OriginalGuestExecutionReceipt)->Result<(),ValueError>{self.receive_execution_key(ScopeKey::Receiver{slot,generation},receipt)}
 pub fn receive_actor_execution_receipt(&mut self,input:RetainedTurnInput,receipt:OriginalGuestExecutionReceipt)->Result<(),ValueError>{self.receive_execution_key(ScopeKey::Actor{input},receipt)}
 fn receive_execution_key(&mut self,key:ScopeKey,receipt:OriginalGuestExecutionReceipt)->Result<(),ValueError>{self.matching_key(key)?;let scope=self.scope.as_mut().unwrap();let budget=scope.execution_pending.ok_or_else(||refusal("original Host execution receipt has no pending authorization"))?;receipt.validate_for(budget)?;let spent=receipt.spent_fuel.ok_or_else(||refusal("original Host execution measurement is unavailable"))?;scope.execution_remaining=scope.execution_remaining.checked_sub(spent).ok_or_else(||refusal("original Host execution receipt exceeds its current scope"))?;scope.execution_spent=scope.execution_spent.checked_add(spent).ok_or_else(||refusal("original Host cumulative execution fuel overflow"))?;scope.execution_pending=None;Ok(())}
 pub fn finish_turn(&mut self,slot:usize,generation:u64)->Result<(RetainedTurnReceipt,u64,u64),ValueError>{self.finish_key(ScopeKey::Receiver{slot,generation})}
 fn finish_key(&mut self,key:ScopeKey)->Result<(RetainedTurnReceipt,u64,u64),ValueError>{let scope=self.matching_key(key)?;if scope.pending.is_some()||scope.execution_pending.is_some(){return Err(refusal("original Host root cannot finish before its held guest receipt is acknowledged"))}let receipt=scope.original.return_original(scope.spent)?;let work=scope.work;if work>self.fuel_remaining{return Err(refusal("original Host returned work exceeds finite operation fuel"))}let execution=scope.execution_spent;if execution>self.execution_fuel_remaining{return Err(refusal("original Host returned VM work exceeds finite operation execution fuel"))}self.fuel_remaining-=work;self.execution_fuel_remaining-=execution;self.scope=None;Ok((receipt,work,execution))}
 pub fn close_step(&mut self,input:RetainedTurnInput)->Result<RetainedCloneStep,OriginalTurnFailure>{self.validate_input(input)?;if self.scope.is_some(){return Err(refusal("original Host source close cannot abandon its suspended receipt").into())}let call=self.context.close_step(input);let step=call.result.map_err(|error|match error{OriginalActorContextError::Refused(error)|OriginalActorContextError::Cancellation(semio_framework_async::CancelTokenRetirementError::Refused(error))=>error,OriginalActorContextError::Cancellation(semio_framework_async::CancelTokenRetirementError::Blocked(_))=>refusal("original Host root cancellation retains a live child")})?;if self.context.terminal_is_empty(){self.ready=false;}Ok(step)}
 pub fn terminal_is_empty(&self)->bool{self.context.terminal_is_empty()&&self.scope.is_none()}
}
impl Drop for GuestRelayOriginalRoot{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original Host root dropped before funded source and guest receipt closure")}}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn add(a:RetainedCloneProgress,b:RetainedCloneProgress)->Result<RetainedCloneProgress,ValueError>{let add=|a:usize,b:usize|a.checked_add(b).ok_or_else(||refusal("original Host cumulative physical receipt overflow"));Ok(RetainedCloneProgress{copied_items:add(a.copied_items,b.copied_items)?,copied_bytes:add(a.copied_bytes,b.copied_bytes)?,retained_capacity_bytes:add(a.retained_capacity_bytes,b.retained_capacity_bytes)?,released_bytes:add(a.released_bytes,b.released_bytes)?})}
